"""Exercise 3: the send_floor_plan tool. These tests are the spec. Make them pass one at a time:

    uv run pytest tests/test_floor_plan.py -x -q
"""

from app.projects import find_project
from tests.conftest import PHONE, payload_of


# Step 1: assets. One PDF per project + configuration, generated by scripts/make_brochures.py.
def test_step1_floor_plan_file_exists_for_every_configuration():
    from app.projects import floor_plan_path
    for ref, config in [("skyline", "2 BHK"), ("skyline", "3 BHK"), ("palm grove", "4 BHK villa"), ("metro", "1 BHK")]:
        path = floor_plan_path(find_project(ref), config)
        assert path.name == f"{find_project(ref)['id']}-{config.lower().replace(' ', '-')}.pdf"
        assert path.read_bytes().startswith(b"%PDF"), f"missing {path}: run scripts/make_brochures.py"


# Step 2: channel. A WhatsApp template with a DOCUMENT header, logged as kind "floor_plan".
def test_step2_whatsapp_payload(env):
    import asyncio
    from app.channels import whatsapp
    r = asyncio.run(whatsapp.send_floor_plan(call_id="c1", phone=PHONE, name="Harsh",
                                             project=find_project("skyline"), config="3 BHK",
                                             url="https://x/static/floor_plans/skyline-heights-3-bhk.pdf"))
    assert r["ok"]
    msg = env.sent("whatsapp", "floor_plan")[0]
    template = payload_of(msg)["template"]
    assert template["name"] == "floor_plan"
    header = template["components"][0]
    assert header["type"] == "header" and header["parameters"][0]["type"] == "document"
    body = [p["text"] for p in template["components"][1]["parameters"]]
    assert body == ["Harsh", "Skyline Heights 3 BHK"]


# Step 3: the tool endpoint the Ringg agent calls mid-call.
def test_step3_tool_sends_matching_plan(env):
    r = env.tool("send-floor-plan", call_id="c1", phone=PHONE, name="Harsh", project="skyline", bhk="3")
    assert r["sent"] is True
    assert "3 BHK" in r["result"] and "WhatsApp" in r["result"]
    link = payload_of(env.sent("whatsapp", "floor_plan")[0])["template"]["components"][0]["parameters"][0]["document"]["link"]
    assert link.endswith("/static/floor_plans/skyline-heights-3-bhk.pdf")
    assert env.lead()["bhk"] == "3 BHK"  # we learned something about the lead: remember it


def test_step3_unknown_configuration_tells_agent_what_exists(env):
    r = env.tool("send-floor-plan", call_id="c1", phone=PHONE, name="Harsh", project="metro one", bhk="4 BHK")
    assert r["sent"] is False
    assert "1 BHK" in r["result"] and "2 BHK" in r["result"]
    assert env.sent("whatsapp", "floor_plan") == []


def test_step3_unknown_project(env):
    r = env.tool("send-floor-plan", call_id="c1", phone=PHONE, project="lodha", bhk="2")
    assert "couldn't match" in r["result"]
